// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        // fund the contract via its receive()
        uint256 seed = 10 ether;
        vm.deal(address(this), seed);
        (bool sent,) = address(c).call{value: seed}("");
        assertTrue(sent);

        // keep amount admissible: any value up to the contract balance
        uint256 bal = address(c).balance;
        amount = bound(amount, 0, bal);

        uint256 before = address(c).balance;
        vm.prank(address(this));
        c.withdraw(amount);

        // Rule: withdraw(v) must move exactly v wei out of the contract.
        assertTrue(address(c).balance == before - amount);
    }

    receive() external payable {}
}
